#!/usr/bin/env python3
"""Jack XIII — Capture 0x14003bea0 with external buffers.

Strategy:
  1. Hook entry of 0x14003bea0: snapshot ctx (8 KB), stack (2 KB), regs.
  2. Hook calls to known helpers (0x140005b50, 0x140003a50) that run
     during the body: on each entry, snapshot the first argument (rcx)
     and the heap buffer it points to (4 KB window).
  3. Hook exit of 0x14003bea0: snapshot final ctx + the same external
     buffers that were observed at entry.
  4. Save vectors with `extra_bufs: [{addr, size, before_hex, after_hex}, ...]`
     so Unicorn can mem_map them at their runtime addresses.

This mirrors the fix Jack III applied to 0x140003a50 but captures
MULTIPLE external buffers (xor-mask writer touches a different region
than state_tick).
"""
import frida, threading, os, json, sys, time

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(HERE)
EXE = os.path.join(REPO, 'pafet_pass8.exe')
OUT = os.path.join(REPO, 'vm_pools_evidence', 'h3bea0_vectors_xiii.json')

AGENT = r"""
const mainMod = Process.enumerateModules().find(m => m.name.toLowerCase().endsWith('.exe'));
const base = mainMod.base;
const BEA0  = base.add(0x3bea0);  // byte-0 atomic writer
const H5B50 = base.add(0x5b50);   // xor-mask writer helper
const H3A50 = base.add(0x3a50);   // state_tick/qword writer helper
const H20   = base.add(0x397239); // host 20 (end-marker)

send({kind:'base', base: base.toString(), size: mainMod.size.toString()});

const EXTRA_BUF_SIZE = 0x1000;  // 4 KB per external buffer

// Reduce MAX to fit 2 MB handler-base dumps in a reasonable JSON size.
// After we validate N/N pass, we can raise this and recapture.

function hex(bytes) {
  const b = new Uint8Array(bytes);
  let s = '';
  for (let i = 0; i < b.length; i++) s += b[i].toString(16).padStart(2,'0');
  return s;
}
function safeHex(p, n) {
  try { return hex(p.readByteArray(n)); } catch(e) { return null; }
}
function safeHexChunked(p, n, chunk) {
  // Frida may fail on huge single reads. Read in `chunk`-byte pieces.
  chunk = chunk || 0x10000;  // 64 KB per read
  let out = '';
  let read = 0;
  while (read < n) {
    const want = Math.min(chunk, n - read);
    let piece;
    try { piece = hex(p.add(read).readByteArray(want)); }
    catch(e) { if (out.length === 0) return null; break; }
    if (!piece) break;
    out += piece;
    read += want;
  }
  return out.length ? out : null;
}

let vectors = [];
let current = null;         // active 0x14003bea0 invocation
let extra_observed = {};    // addr -> {size, before_hex, before_captured_at}
let bea0_count = 0;
const MAX = 3;              // smaller sample to keep JSON manageable with 2 MB dumps

Interceptor.attach(BEA0, {
  onEnter(args) {
    if (bea0_count >= MAX) return;
    const ctx_ptr = this.context.rcx;
    const rsp     = this.context.rsp;
    const regs = {
      rcx: ctx_ptr.toString(),
      rdx: this.context.rdx.toString(),
      r8:  this.context.r8.toString(),
      r9:  this.context.r9.toString(),
      rbp: this.context.rbp.toString(),
      rsi: this.context.rsi.toString(),
      rdi: this.context.rdi.toString(),
      rbx: this.context.rbx.toString(),
      rsp: rsp.toString(),
    };
    const ctx_hex = safeHex(ctx_ptr, 0x2000);          // 8 KB ctx
    const stack_hex = safeHex(rsp, 0x800);             // 2 KB stack
    let stack_below = null;
    try { stack_below = safeHex(rsp.sub(0x800), 0x800); } catch(e) {}

    current = {
      regs,
      ctx_hex,
      stack_hex,
      stack_below_hex: stack_below,
      extra: {},
    };
    extra_observed = {};

    // Scan the whole ctx (8 KB) for pointer-like qwords and dump windows.
    // Use LARGER windows for pointers that look like handler-trampoline tables
    // (ctx[0xf48]) since the handler base is followed by hundreds of KB of
    // JIT-generated trampolines.
    const SMALL_WINDOW = 0x4000;    // 16 KB
    const BIG_WINDOW   = 0x200000;  // 2 MB for suspected handler tables
    const ctx_hi = ctx_ptr.add(0x2000);
    const seen = {};

    function dump_at(p, size, label) {
      if (p.isNull()) return;
      if (p.compare(ptr('0x100000')) < 0) return;
      if (p.compare(ptr('0x7FFFFFFFFFFF')) > 0) return;
      if (p.compare(ctx_ptr) >= 0 && p.compare(ctx_hi) < 0) return;
      const key_base = p.and(ptr('0xFFFFFFFFFFFFC000'));
      const key_s = key_base.toString();
      const prev = current.extra[key_s];
      if (prev && prev.size >= size) return;
      // Use Process.findRangeByAddress to clamp size to actual mapped region.
      try {
        const rng = Process.findRangeByAddress(key_base);
        if (rng) {
          const rng_end = rng.base.add(rng.size);
          const want_end = key_base.add(size);
          const effective_end = want_end.compare(rng_end) > 0 ? rng_end : want_end;
          const effective_size = effective_end.sub(key_base).toInt32();
          const reader = effective_size > 0x10000 ? safeHexChunked : safeHex;
          const bytes = reader(key_base, effective_size);
          if (bytes) {
            current.extra[key_s] = {size: bytes.length / 2, before_hex: bytes, src: label + '|' + rng.protection};
            return;
          }
        }
      } catch(e) {}
      // Fallback: original attempt
      const reader = size > 0x10000 ? safeHexChunked : safeHex;
      const bytes = reader(key_base, size);
      if (bytes) {
        current.extra[key_s] = {size: bytes.length / 2, before_hex: bytes, src: label + '|fallback'};
      }
    }

    // Handler trampoline base: ctx[0xf48]. Capture a LARGE window (256 KB).
    try { dump_at(ctx_ptr.add(0xf48).readPointer(), BIG_WINDOW, 'entry.ctx+f48.BIG'); } catch(e) {}

    // Handler table index: ctx[0xf40]
    try { dump_at(ctx_ptr.add(0xf40).readPointer(), SMALL_WINDOW, 'entry.ctx+f40'); } catch(e) {}

    // Generic ctx scan: for every qword that looks like a heap pointer,
    // capture a 16 KB window.
    for (let off = 0; off < 0x2000; off += 8) {
      try {
        const p = ctx_ptr.add(off).readPointer();
        dump_at(p, SMALL_WINDOW, 'ctx_scan+' + off.toString(16));
      } catch(e) {}
    }

  },
  onLeave(retval) {
    if (bea0_count >= MAX || !current) return;
    bea0_count++;
    const ctx_ptr = ptr(current.regs.rcx);
    const rsp     = ptr(current.regs.rsp);
    current.after = {
      rax: retval.toString(),
      ctx_hex: safeHex(ctx_ptr, 0x2000),
      stack_hex: safeHex(rsp, 0x800),
    };
    // Re-dump each extra buffer at its runtime address to get its AFTER state
    for (const addr_s of Object.keys(current.extra)) {
      const info = current.extra[addr_s];
      info.after_hex = safeHex(ptr(addr_s), info.size);
    }
    vectors.push(current);
    current = null;
    if (bea0_count === MAX) {
      send({kind:'done', vectors});
    }
  }
});

function capture_extra(addr_ptr, size, src) {
  if (!current) return;
  if (addr_ptr.isNull()) return;
  const addr_s = addr_ptr.toString();
  // Dedup within the same invocation
  if (current.extra[addr_s]) return;
  // Skip if the buffer overlaps the already-captured ctx window
  const ctx_ptr = ptr(current.regs.rcx);
  const ctx_end = ctx_ptr.add(0x2000);
  if (addr_ptr.compare(ctx_ptr) >= 0 && addr_ptr.compare(ctx_end) < 0) return;
  // Skip if within the captured stack window [rsp-0x800, rsp+0x800]
  const rsp = ptr(current.regs.rsp);
  const stack_lo = rsp.sub(0x800);
  const stack_hi = rsp.add(0x800);
  if (addr_ptr.compare(stack_lo) >= 0 && addr_ptr.compare(stack_hi) < 0) return;
  // Capture
  const bytes = safeHex(addr_ptr, size);
  if (bytes) {
    current.extra[addr_s] = {size, before_hex: bytes, src};
  }
}

// H5B50 — the xor-mask writer. Jack III captures showed its args: rcx=ctx,
// but it also dereferences [ctx+0x1b0] (output buffer) and reads a splitmix-
// derived address. Capture rcx-pointed buffer plus [rcx+0x1b0] contents.
Interceptor.attach(H5B50, {
  onEnter(args) {
    if (!current) return;
    const r1 = this.context.rcx;
    const r8 = this.context.r8;
    const r9 = this.context.r9;
    capture_extra(r1, EXTRA_BUF_SIZE, 'h5b50.rcx');
    // r8/r9 are commonly literals here but might be pointers; capture if large
    try {
      if (r8.toInt32() !== r8.toUInt32() || r8.compare(ptr('0x100000')) > 0) {
        capture_extra(r8, EXTRA_BUF_SIZE, 'h5b50.r8');
      }
    } catch(e) {}
    try {
      if (r9.compare(ptr('0x100000')) > 0) {
        capture_extra(r9, EXTRA_BUF_SIZE, 'h5b50.r9');
      }
    } catch(e) {}
    // Also follow [rcx+0x1b0] -> buffer
    try {
      const p = r1.add(0x1b0).readPointer();
      capture_extra(p, EXTRA_BUF_SIZE, 'h5b50.ctx+1b0');
    } catch(e) {}
    try {
      const p = r1.add(0xa8).readPointer();
      capture_extra(p, EXTRA_BUF_SIZE, 'h5b50.ctx+a8');
    } catch(e) {}
    try {
      const p = r1.add(0x1160).readPointer();
      capture_extra(p, EXTRA_BUF_SIZE, 'h5b50.ctx+1160');
    } catch(e) {}
  }
});

Interceptor.attach(H3A50, {
  onEnter(args) {
    if (!current) return;
    const r1 = this.context.rcx;
    const r2 = this.context.rdx;
    const r8 = this.context.r8;
    capture_extra(r1, EXTRA_BUF_SIZE, 'h3a50.rcx');
    try {
      if (r2.compare(ptr('0x100000')) > 0) capture_extra(r2, EXTRA_BUF_SIZE, 'h3a50.rdx');
    } catch(e) {}
    try {
      if (r8.compare(ptr('0x100000')) > 0) capture_extra(r8, EXTRA_BUF_SIZE, 'h3a50.r8');
    } catch(e) {}
    try {
      const p = r1.add(0x1b0).readPointer();
      capture_extra(p, EXTRA_BUF_SIZE, 'h3a50.ctx+1b0');
    } catch(e) {}
    try {
      const p = r1.add(0x1160).readPointer();
      capture_extra(p, EXTRA_BUF_SIZE, 'h3a50.ctx+1160');
    } catch(e) {}
  }
});

Interceptor.attach(H20, {
  onEnter() {
    // Flush anything partial
    if (vectors.length > 0 || bea0_count > 0) {
      send({kind:'done', vectors, bea0_count});
    } else {
      send({kind:'done', vectors: [], bea0_count: 0});
    }
  }
});
"""

def capture(user_bytes, serial=b'serial01', timeout=60):
    dev = frida.get_local_device()
    pid = dev.spawn([EXE], stdio='pipe')
    done = threading.Event()
    result = {}
    def on_msg(m, _):
        if m['type'] == 'send':
            p = m['payload']
            if p.get('kind') == 'base':
                result['pe_base'] = p['base']
                result['pe_size'] = p['size']
            elif p.get('kind') == 'done':
                result.update(p)
                done.set()
        elif m['type'] == 'error':
            print('[frida err]', m)
    dev.on('output', lambda p, f, d: None)
    sess = dev.attach(pid)
    scr = sess.create_script(AGENT)
    scr.on('message', on_msg)
    scr.load()
    dev.resume(pid)
    dev.input(pid, user_bytes + b'\r\n' + serial + b'\r\n')
    done.wait(timeout)
    try: dev.kill(pid)
    except: pass
    return result

def main():
    out = {}
    for label, u in [('alice', b'alice'), ('ramon', b'ramon')]:
        print(f'=== Capturing {label} ===', flush=True)
        r = capture(u, timeout=90)
        vecs = r.get('vectors', [])
        print(f'  captured {len(vecs)} 0x14003bea0 invocations')
        if vecs:
            v0 = vecs[0]
            extra = v0.get('extra', {})
            print(f'  vec[0] extra bufs: {len(extra)} regions')
            for addr, info in list(extra.items())[:6]:
                print(f'    {addr} size={info["size"]} src={info["src"]}')
        out[label] = {
            'count': len(vecs),
            'vectors': vecs,
            'pe_base': r.get('pe_base'),
            'pe_size': r.get('pe_size'),
        }
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, 'w') as fh:
        json.dump(out, fh)
    print(f'[+] saved {OUT}')
    print(f'    size: {os.path.getsize(OUT)} B')

if __name__ == '__main__':
    main()

// main_h3880_native_test_vA.cpp  --  Jack V-A deliverable.
// Differential test harness for the native port of 0x140003880.
// Loads the 5 captured runtime vectors from
// vm_pools_evidence/h3880_fullctx_ext_ivB.json and compares post-call
// state against the recorded exit state byte-exact.

#include "pafet_h3880_native_vA.h"
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

static std::vector<uint8_t> hex2bytes(const std::string& h) {
    std::vector<uint8_t> out;
    out.reserve(h.size() / 2);
    for (size_t i = 0; i + 1 < h.size(); i += 2) {
        char hi = h[i], lo = h[i+1];
        auto nib = [](char c) -> int {
            if (c >= '0' && c <= '9') return c - '0';
            if (c >= 'a' && c <= 'f') return c - 'a' + 10;
            if (c >= 'A' && c <= 'F') return c - 'A' + 10;
            return 0;
        };
        out.push_back(static_cast<uint8_t>((nib(hi) << 4) | nib(lo)));
    }
    return out;
}

// N-th occurrence of a string-valued "key":"..." in the JSON (0-indexed).
static std::string pick_nth_s(const std::string& json, const std::string& key, int n) {
    std::string needle = "\"" + key + "\"";
    size_t p = 0;
    for (int i = 0; i <= n; i++) {
        p = json.find(needle, p);
        if (p == std::string::npos) return {};
        if (i < n) p += needle.size();
    }
    size_t colon = json.find(':', p + needle.size());
    size_t q1 = json.find('"', colon);
    if (q1 == std::string::npos) return {};
    size_t q2 = json.find('"', q1 + 1);
    if (q2 == std::string::npos) return {};
    return json.substr(q1 + 1, q2 - q1 - 1);
}

static uint64_t hex2u64(const std::string& s) {
    uint64_t v = 0;
    size_t start = 0;
    if (s.size() >= 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) start = 2;
    for (size_t i = start; i < s.size(); i++) {
        char c = s[i]; int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else break;
        v = (v << 4) | d;
    }
    return v;
}

int main(int argc, char** argv) {
    const char* json_path = argc > 1 ? argv[1]
        : "vm_pools_evidence/h3880_fullctx_ext_ivB.json";

    std::ifstream fh(json_path);
    if (!fh.is_open()) {
        std::printf("ERROR: cannot open %s\n", json_path);
        return 2;
    }
    std::stringstream ss; ss << fh.rdbuf();
    std::string json = ss.str();

    int total = 0, pass = 0;
    for (int i = 0; i < 5; i++) {
        std::string entry_ctx_hex = pick_nth_s(json, "entry_ctx", i);
        std::string exit_ctx_hex  = pick_nth_s(json, "exit_ctx",  i);
        std::string entry_b2_hex  = pick_nth_s(json, "entry_buf2", i);
        std::string exit_b2_hex   = pick_nth_s(json, "exit_buf2",  i);
        std::string rdx_hex       = pick_nth_s(json, "rdx", i);
        if (entry_ctx_hex.empty() || exit_ctx_hex.empty()
            || entry_b2_hex.empty() || exit_b2_hex.empty()
            || rdx_hex.empty()) {
            std::printf("cap#%d: missing hex fields; skipping\n", i);
            continue;
        }

        std::vector<uint8_t> entry_ctx = hex2bytes(entry_ctx_hex);
        std::vector<uint8_t> exit_ctx  = hex2bytes(exit_ctx_hex);
        std::vector<uint8_t> buf2_in   = hex2bytes(entry_b2_hex);
        std::vector<uint8_t> buf2_ex   = hex2bytes(exit_b2_hex);
        uint64_t rdx_arg = hex2u64(rdx_hex);

        pafet::handler_h3880(entry_ctx.data(), buf2_in.data(), rdx_arg);

        bool ctx_ok  = (entry_ctx == exit_ctx);
        bool buf2_ok = (buf2_in == buf2_ex);

        total++;
        if (ctx_ok && buf2_ok) {
            pass++;
            std::printf("cap#%d (rdx=%s): OK  (ctx=OK buf2=OK)\n", i, rdx_hex.c_str());
        } else {
            std::printf("cap#%d (rdx=%s): FAIL  ctx=%s buf2=%s\n",
                i, rdx_hex.c_str(), ctx_ok?"OK":"DIF", buf2_ok?"OK":"DIF");

            auto first_diff = [&](const std::vector<uint8_t>& a, const std::vector<uint8_t>& b, const char* name) {
                size_t sz = a.size() < b.size() ? a.size() : b.size();
                for (size_t k = 0; k < sz; k++) {
                    if (a[k] != b[k]) {
                        std::printf("    %s first diff @0x%zx: got=%02x want=%02x\n",
                            name, k, a[k], b[k]);
                        return;
                    }
                }
                if (a.size() != b.size()) {
                    std::printf("    %s size diff: got=%zu want=%zu\n", name, a.size(), b.size());
                }
            };
            if (!ctx_ok)  first_diff(entry_ctx, exit_ctx, "ctx");
            if (!buf2_ok) first_diff(buf2_in, buf2_ex, "buf2");
        }
    }

    std::printf("\n[SUMMARY] %d/%d captures reproduced byte-exact\n", pass, total);
    return pass == total ? 0 : 1;
}

#!/usr/bin/env python3
"""Jack XI — Unified capture: IR (resolver sequence) + atomic byte-writer pairs
for a given username. Produces a JSON compatible with run_ir_with_user_dynamic.

The atomic byte-writer pairs are detected by watching the output buffer at
[*ctx+0x5e8]; whenever a new input byte becomes present (NOT a reversed-ASCII
copy), the (ch, op) just executed is recorded as the atomic writer for that
byte position.

Output JSON structure:
  {
    "user": "...",
    "serial": "...",
    "atomic_pairs": [[ch, op, byte_index], ...],  # byte_index is 0..len(user)-1
    "program": [{idx, ch, op, operands, next_op_encoded}, ...]
  }
"""
import frida, threading, os, json, sys

HERE = os.path.dirname(os.path.abspath(__file__))
EXE = os.path.join(HERE, '..', 'pafet_pass8.exe')

AGENT = r"""
const base = Process.enumerateModules().find(m => m.name.toLowerCase().endsWith('.exe')).base;
const RESOLVER = base.add(0x3ebb0);
const OPREADER = base.add(0x74d0);
const H20      = base.add(0x397239);

let callN = 0;
let ctx = null;
let last_bytes = null;
let transitions = [];
let program = [];
let last_op_rax = -1;

Interceptor.attach(RESOLVER, {
  onEnter() {
    callN++;
    const r_ctx = this.context.rcx;
    const r_ch  = this.context.rdx.toInt32();
    const r_op  = this.context.r8.toInt32();
    if (!ctx) ctx = r_ctx;
    this.callN = callN;
    this.ch = r_ch;
    this.op = r_op;
    try {
      const p = ctx.add(0x5e8).readPointer();
      const b = Array.from(new Uint8Array(p.readByteArray(64)))
        .map(x => x.toString(16).padStart(2,'0')).join('');
      if (b !== last_bytes) {
        transitions.push({
          call: callN,
          ch:   r_ch,
          op:   r_op,
          bytes_before: last_bytes || '',
          bytes_after:  b,
        });
        last_bytes = b;
      }
    } catch(e) {}
  },
  onLeave(retval) {
    // retval of resolver is the handler; op_read returns the NEXT opcode
    // but we need the operand reader's rax, not the resolver's. The threaded
    // code property uses op_read's return. We capture it separately below.
  }
});

// Capture operand reader to collect operands and the next_op_encoded
let pending_operand = null;
Interceptor.attach(OPREADER, {
  onEnter(args) { this.active = true; },
  onLeave(retval) {
    if (this.active) {
      last_op_rax = retval.toInt32();
    }
  }
});

Interceptor.attach(H20, {
  onEnter() {
    send({kind:'done', transitions: transitions, total: callN});
  }
});
"""


# Simpler: we don't actually need operand reader hook for THIS fork's goal.
# We just need the IR (ch, op per resolver call) + atomic transitions.
# Build the IR trace by hooking only the resolver.

AGENT_SIMPLE = r"""
const base = Process.enumerateModules().find(m => m.name.toLowerCase().endsWith('.exe')).base;
const RESOLVER = base.add(0x3ebb0);
const OPREADER = base.add(0x74d0);
const H20      = base.add(0x397239);

// Known atomic-writer handler VAs (observed in alice): poll on entry+leave
// of these specifically — they are where the output bytes are produced.
const ATOMIC_WRITERS = [0x3bea0, 0x15820, 0x25020, 0x14a00, 0x216d0];

let callN = 0;
let ctx = null;
let last_bytes = null;
let transitions = [];
let program = [];

// Record the (ch, op) context from the most recent resolver call.
let last_ch = -1;
let last_op = -1;

function poll_buffer(ch, op, src) {
  if (!ctx) return;
  try {
    const p = ctx.add(0x5e8).readPointer();
    const b = Array.from(new Uint8Array(p.readByteArray(128)))
      .map(x => x.toString(16).padStart(2,'0')).join('');
    if (b !== last_bytes) {
      transitions.push({
        call: callN,
        ch: ch, op: op,
        bytes: b, src: src,
      });
      last_bytes = b;
    }
  } catch(e) {}
}

Interceptor.attach(RESOLVER, {
  onEnter() {
    callN++;
    const r_ctx = this.context.rcx;
    last_ch = this.context.rdx.toInt32();
    last_op = this.context.r8.toInt32();
    if (!ctx) ctx = r_ctx;
    program.push({idx: callN - 1, ch: last_ch, op: last_op});
    poll_buffer(last_ch, last_op, 'resolver_enter');
  },
  onLeave() {
    poll_buffer(last_ch, last_op, 'resolver_leave');
  }
});

// Dense polling on the operand reader (~1200 triggers vs 629 resolver)
Interceptor.attach(OPREADER, {
  onLeave() {
    poll_buffer(last_ch, last_op, 'opreader_leave');
  }
});

// Dense polling at the entry+leave of each known atomic-writer handler
for (const rva of ATOMIC_WRITERS) {
  try {
    Interceptor.attach(base.add(rva), {
      onEnter() { poll_buffer(last_ch, last_op, 'writer_enter_' + rva.toString(16)); },
      onLeave() { poll_buffer(last_ch, last_op, 'writer_leave_' + rva.toString(16)); }
    });
  } catch(e) {}
}

Interceptor.attach(H20, {
  onEnter() {
    send({kind:'done', program: program, transitions: transitions});
  }
});
send({kind:'ready'});
"""


def capture(user_bytes, serial=b'serial01', timeout=180):
    dev = frida.get_local_device()
    pid = dev.spawn([EXE], stdio='pipe')
    done = threading.Event(); result = {}
    def on_msg(m, _):
        if m['type'] == 'send' and m['payload'].get('kind') == 'done':
            result.update(m['payload']); done.set()
    dev.on('output', lambda p, f, d: None)
    sess = dev.attach(pid)
    scr = sess.create_script(AGENT_SIMPLE)
    scr.on('message', on_msg)
    scr.load()
    dev.resume(pid)
    dev.input(pid, user_bytes + b'\r\n' + serial + b'\r\n')
    done.wait(timeout)
    try: dev.kill(pid)
    except Exception: pass
    return result


def f_user_oracle(u):
    """f_user(c, i) = ((c XOR 0x5A) + 7 + 3*i) & 0xFF, c reversed"""
    out = []
    for i in range(len(u)):
        c = u[len(u) - 1 - i]
        out.append(((c ^ 0x5A) + 7 + 3 * i) & 0xFF)
    return bytes(out)


def identify_atomic_pairs(transitions, user, expected_output):
    """Detect atomic byte-writer pairs across the transition stream.

    Original strict rule (one byte diff per transition) misses inputs whose
    writes land between two consecutive resolver polls (common with
    repeated-byte inputs like 'a'*23 where the pipeline runs faster).

    Relaxed rule:
      - For each transition, iterate through diffs in position order.
      - For each diff that equals the next expected atomic byte, record
        the current (ch, op) as the atomic writer for that position.
      - This assumes contiguous writes within a single transition were
        made under the same (ch, op) context (sequential-handler
        hypothesis). Validity is checked downstream when the native
        interpreter runs the resulting atomic_pairs sequence byte-exact
        against the oracle.
    """
    L = len(user)
    if L == 0:
        return [], 0

    atomic_pairs = []
    prev_buf = bytes(64)  # initial zero
    for t in transitions:
        bytes_hex = t.get('bytes', '')
        if not bytes_hex:
            continue
        curr_full = bytes.fromhex(bytes_hex)
        if len(curr_full) < L:
            continue
        curr = curr_full[:L]
        prev = prev_buf[:L]
        diffs = [i for i in range(L) if prev[i] != curr[i]]
        for i in sorted(diffs):
            # Only accept writes that advance the sequential byte position
            # and match the oracle. This guards against intermediate
            # non-atomic states (e.g. reversed-ASCII copy stage).
            if i == len(atomic_pairs) and curr[i] == expected_output[i]:
                atomic_pairs.append([t['ch'], t['op'], i])
            if len(atomic_pairs) == L:
                return atomic_pairs, L
        prev_buf = curr_full

    return atomic_pairs, len(atomic_pairs)


def main():
    out_dir = os.path.join(HERE, '..', 'vm_pools_evidence')
    os.makedirs(out_dir, exist_ok=True)

    INPUTS = [
        ('empty', b''),
        ('a_len1', b'a'),
        ('alice_len5', b'alice'),
        ('ramon_len5', b'ramon'),
        ('alice123_len8', b'alice123'),
        ('ramonbarcelona_len14', b'ramonbarcelona'),
        ('a_x23', b'a' * 23),
        ('a_x24', b'a' * 24),
        ('a_x25', b'a' * 25),
    ]

    results = {}
    for label, u in INPUTS:
        print(f'\n=== Capturing {label} (user={u!r}, len={len(u)}) ===', flush=True)
        try:
            r = capture(u)
        except Exception as e:
            print(f'  ERROR: {e}', flush=True)
            results[label] = {'error': str(e)}
            continue

        program = r.get('program', [])
        transitions = r.get('transitions', [])
        print(f'  resolver calls: {len(program)}')
        print(f'  buffer transitions: {len(transitions)}')

        expected = f_user_oracle(u)
        atomic_pairs, found = identify_atomic_pairs(transitions, u, expected)
        print(f'  expected f_user: {expected.hex()}')
        print(f'  atomic byte-writer pairs identified: {len(atomic_pairs)} / {len(u)}')
        for ap in atomic_pairs:
            print(f'    byte {ap[2]}: (ch={ap[0]}, op={ap[1]})')

        # Compute next_op_encoded from the program sequence
        # Since we don't capture op_reader separately, derive it from the sequence
        # of consecutive resolver (ch, op) pairs: next_op_encoded of instr i = op of instr i+1.
        program_full = []
        for i, p in enumerate(program):
            next_op = program[i + 1]['op'] if i + 1 < len(program) else 0
            program_full.append({
                'idx': p['idx'],
                'ch': p['ch'],
                'op': p['op'],
                'operands': [],
                'next_op_encoded': next_op,
            })

        out = {
            'user': u.decode('latin-1'),
            'len': len(u),
            'serial': 'serial01',
            'expected_f_user_hex': expected.hex(),
            'atomic_pairs': atomic_pairs,
            'atomic_pairs_found': found,
            'program': program_full,
            'transitions_count': len(transitions),
        }
        out_path = os.path.join(out_dir, f'user_vm_ir_{label}_xi.json')
        with open(out_path, 'w') as fh:
            json.dump(out, fh, indent=1)
        print(f'  saved {out_path}')
        results[label] = {
            'instructions': len(program),
            'atomic_found': found,
            'atomic_expected': len(u),
        }

    print('\n=== SUMMARY ===')
    for label, info in results.items():
        if 'error' in info:
            print(f'  {label}: ERROR {info["error"]}')
        else:
            ok = 'OK' if info['atomic_found'] == info['atomic_expected'] else 'PARTIAL'
            print(f'  {label}: {info["instructions"]} instr, '
                  f'{info["atomic_found"]}/{info["atomic_expected"]} atomic pairs [{ok}]')


if __name__ == '__main__':
    main()

