static std::string hex(const uint8_t* p, size_t n) {
    static const char d[] = "0123456789abcdef";
    std::string s; s.reserve(n*2);
    for (size_t i = 0; i < n; i++) { s.push_back(d[p[i]>>4]); s.push_back(d[p[i]&15]); }
    return s;
}

