//
// This header provides a public-domain SHA-256 implementation (based on
// Brad Conte's SHA-256 reference, public domain). The pafet_shavm::compute
// wrapper exposes the same contract as the SHA-VM: input bytes + length
// -> 32-byte digest.

#include <cstdint>
#include <cstring>

namespace pafet_shavm {

inline uint32_t rotr(uint32_t x, uint32_t n) { return (x >> n) | (x << (32 - n)); }

static const uint32_t K[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
