    int pass = 0, fail = 0, skip = 0;
    for (const auto& c : cases) {
        int r = run_one(c.label, c.path);
        if (r == 0) pass++;
        else if (r == 2) skip++;
        else fail++;
    }

    std::printf("\n==============================================================\n");
    std::printf("[JACK XV SUMMARY] passed=%d  failed=%d  skipped=%d  total=%zu\n",
                pass, fail, skip, sizeof(cases)/sizeof(cases[0]));
    std::printf("==============================================================\n");
    return (fail == 0) ? 0 : 1;
}

